# hook strcmp: 打印每次比较的两端字符串
// hook.js
const strcmp = Module.findExportByName(null, "strcmp");
Interceptor.attach(strcmp, {
  onEnter(args) {
    this.a = Memory.readUtf8String(args[0]);
    this.b = Memory.readUtf8String(args[1]);
    console.log("strcmp(", this.a, ",", this.b, ")");
  },
  onLeave(retval) {
    console.log("  =>", retval.toInt32());
  }
});
# 运行
frida -n target_process -l hook.js
# 每次比较都打印两端字符串 -> 直接暴露比对明文

