# 更广的 hook: 打印输入输出与调用栈
// hook2.js
const t = Module.findExportByName(null, "Decrypt");
Interceptor.attach(t, {
  onEnter(args) {
    console.log("Decrypt in:", Memory.readByteArray(args[0],64));
    console.log(Thread.backtrace(this.context, Backtracer.ACCURATE)
                .map(DebugSymbol.fromAddress).join("\n"));
  },
  onLeave(ret) {
    console.log("Decrypt out:", Memory.readByteArray(ret,64));
  }
});
# 移动端同理; 始终只在受控设备分析授权样本

# Android native + 动态验证(Frida)
# 1) 从 jadx 找到 native 方法名
# 2) 找 .so 里对应导出符号
readelf -s lib/libnative.so | grep Java_
# 3) Frida hook 该符号观察参数/返回值
// frida hook Java 层也可以:
Java.perform(function(){
  var C = Java.use("com.app.Main");
  C.check.overload("java.lang.String")
   .implementation = function(s){
     console.log("input:", s);
     var r = this.check(s);
     console.log("result:", r); return r;
   };
});
# 始终在受控越狱/root 设备上分析持有授权的样本
